// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(uint256 msgValue, uint256 dealAmount) public {
        vm.assume(msgValue >= 0);
        vm.assume(dealAmount >= msgValue);
        msgValue = bound(msgValue, 0, address(c).balance);
        dealAmount = bound(dealAmount, msgValue, type(uint96).max);

        Reverter reverter = new Reverter();
        vm.deal(address(this), dealAmount);
        vm.prank(address(this));
        bool ok;
        try c.Command{value: msgValue}(address(reverter), "") {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
